import{_ as t,o,c as a,a6 as r}from"./chunks/framework.DMOj2-2K.js";const m=JSON.parse('{"title":"Status & roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"reference/roadmap.md","filePath":"reference/roadmap.md"}'),s={name:"reference/roadmap.md"};function i(n,e,d,l,c,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="status-roadmap" tabindex="-1">Status &amp; roadmap <a class="header-anchor" href="#status-roadmap" aria-label="Permalink to &quot;Status &amp; roadmap&quot;">​</a></h1><p>Cluub 0.1 is in <strong>beta</strong>. Here is exactly what exists today and what comes next.</p><h2 id="working-today" tabindex="-1">Working today <a class="header-anchor" href="#working-today" aria-label="Permalink to &quot;Working today&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Status</th></tr></thead><tbody><tr><td>Lexer, parser, checker, code generator, runtime and CLI (zero dependencies, ~3,300 lines)</td><td>✅</td></tr><tr><td>Models with validation, stores (memory + JSON file), clients</td><td>✅</td></tr><tr><td>Services, typed and validated APIs, dependency injection</td><td>✅</td></tr><tr><td>Pages, components, layouts, reactive state, routing, toasts</td><td>✅</td></tr><tr><td>Enforced folder structure, layer rules, naming rules</td><td>✅</td></tr><tr><td><code>ask ai</code>, <code>as Model</code>, <code>as one of</code>; Claude, OpenAI, Gemini, Ollama</td><td>✅ (verified offline with the fake AI; live provider calls not yet tested end to end)</td></tr><tr><td>Generated tests for models, services, apis, pages and buttons</td><td>✅</td></tr><tr><td>Headless full-stack UI tests</td><td>✅</td></tr><tr><td><code>cluub explain</code> for PO / BA / QA / dev</td><td>✅</td></tr><tr><td><code>cluub make</code> (AI writes code, compiler-checked repair loop)</td><td>✅ (built; needs an AI key to run)</td></tr><tr><td>CLI: new, dev (live reload), check, test, build, start, errors</td><td>✅</td></tr><tr><td>Docs with playground</td><td>✅</td></tr></tbody></table><h2 id="known-limits" tabindex="-1">Known limits <a class="header-anchor" href="#known-limits" aria-label="Permalink to &quot;Known limits&quot;">​</a></h2><ul><li><strong>Type checking is partial.</strong> Names, dependencies, fields in model construction, call arguments and layers are checked at compile time; values are checked at runtime boundaries (models, apis). Full type inference is next.</li><li><strong>Runtime errors point to generated JavaScript</strong>, not to the <code>.clb</code> line. Source maps are planned.</li><li>Stores are memory or JSON files: fine for prototypes and small apps, not for high write volume.</li><li>Components are stateless by design; page state covers most needs.</li><li>No auth, sessions, file uploads or websockets yet.</li></ul><h2 id="road-to-1-0-enterprise-ready" tabindex="-1">Road to 1.0 (enterprise-ready) <a class="header-anchor" href="#road-to-1-0-enterprise-ready" aria-label="Permalink to &quot;Road to 1.0 (enterprise-ready)&quot;">​</a></h2><h3 id="ui-and-components" tabindex="-1">UI and components <a class="header-anchor" href="#ui-and-components" aria-label="Permalink to &quot;UI and components&quot;">​</a></h3><p>Today Cluub renders its built-in elements (<code>button</code>, <code>card</code>, <code>row</code>, <code>input</code>…) with a small hand-written virtual DOM and <strong>plain CSS</strong> (one theme file with variables, light/dark mode, the brand palette). There is no Tailwind and no component library yet.</p><ol><li><strong>Cluub UI kit</strong>: accessible, themeable ready-made components in the spirit of MUI, Chakra and shadcn/ui: data table (sort, filter, paginate), modal, drawer, tabs, menu, toast, date picker, autocomplete, file upload, charts, form builder with field errors.</li><li><strong>Component state</strong> and slots for custom components.</li><li><strong>Styling options</strong>: design tokens, multiple themes, optional Tailwind-style utility classes, CSS modules.</li><li>Routing extras: nested routes, route guards, query parameters, code splitting.</li></ol><h3 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h3><ol start="5"><li><strong>Database stores</strong>: <code>store Orders holds Order in postgres | mysql | sqlite | mongodb</code>, with migrations generated from models, indexes, transactions and seeding.</li><li><strong>Choose a database when creating an app</strong>: <code>npm create cluub</code> asks SQL (PostgreSQL, MySQL, SQLite) or NoSQL (MongoDB) or none, writes the connection config and a Docker Compose service for it.</li></ol><h3 id="robustness" tabindex="-1">Robustness <a class="header-anchor" href="#robustness" aria-label="Permalink to &quot;Robustness&quot;">​</a></h3><ol start="7"><li><strong>Full static type checker</strong> with inference: wrong field access, wrong return types and nothing-safety caught at compile time.</li><li><strong>Source maps</strong>, so runtime errors point to the <code>.clb</code> line.</li><li><strong>Formatter</strong> (<code>cluub fmt</code>), plus a <strong>language server</strong> and <strong>VS Code extension</strong> with inline errors, completion, hover docs and rename.</li><li><strong>Auto-correct</strong>: <code>cluub fix</code> applies safe fixes for diagnostics (spelling suggestions, missing <code>uses</code>, naming, layer moves); <code>cluub dev --fix</code> and <strong>fix on save</strong> in the editor extension; a &quot;auto-fix on save&quot; choice when creating an app.</li><li>Fuzz and property tests for the compiler, a conformance test suite, mutation testing of generated tests, coverage reports.</li><li>Stable language specification, semantic versioning, deprecation policy and migration tool (<code>cluub migrate</code>).</li></ol><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ol start="13"><li><strong>Authentication and authorization</strong>: sessions, OAuth/OIDC (Google, Microsoft, Okta), roles and permissions declared in the language (<code>page Admin ... for role &quot;admin&quot;</code>).</li><li>CSRF tokens for cookie sessions, rate limiting, request size and timeout policies, configurable CORS.</li><li>Secrets from cloud vaults (AWS Secrets Manager, Azure Key Vault, GCP Secret Manager); audit logging.</li><li>Security hardening: independent security audit, threat model, signed releases and npm provenance, SBOM, dependency-free supply chain kept by policy.</li></ol><h3 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h3><ol start="17"><li><strong>Docker</strong>: <code>cluub build --docker</code> (multi-stage, non-root image) and generated <code>docker-compose.yml</code> with the chosen database.</li><li><strong>CI/CD</strong>: generated GitHub Actions / GitLab CI / Azure Pipelines that run <code>cluub check</code>, <code>cluub test</code> and deploy.</li><li><strong>Cloud deploy</strong>: <code>cluub deploy</code> targets for AWS, Azure, Google Cloud, Vercel, Fly.io and Kubernetes (Helm chart).</li><li>Observability: structured logs, health and readiness routes, metrics (Prometheus/OpenTelemetry), tracing.</li><li>Performance: clustering, caching, streaming AI replies, websockets, background jobs and scheduled tasks.</li></ol><h3 id="ai" tabindex="-1">AI <a class="header-anchor" href="#ai" aria-label="Permalink to &quot;AI&quot;">​</a></h3><ol start="22"><li>AI tools and agents with typed, permissioned access to service actions; streaming replies in the UI; usage and cost limits per user key.</li></ol>',20)])])}const h=t(s,[["render",i]]);export{m as __pageData,h as default};
